// ====== helpers: recursive move & delete ======
function rmove($src, $dst) {
    if (is_dir($src)) {
        if (!is_dir($dst)) {
            if (!mkdir($dst, 0755, true)) {
                throw new Exception("Failed to create directory: $dst");
            }
        }
        $items = scandir($src);
        foreach ($items as $item) {
            if ($item === '.' || $item === '..') {
                continue;
            }
            rmove("$src/$item", "$dst/$item");
        }
        return true;
    } else {
        if (file_exists($dst)) {
            @unlink($dst);
        }
        if (@rename($src, $dst)) {
            return true;
        }
        if (!@copy($src, $dst)) {
            throw new Exception("Failed to move file $src to $dst");
        }
        @unlink($src);
        return true;
    }
}

function rrmdir($dir) {
    if (!is_dir($dir)) {
        return;
    }
    $items = scandir($dir);
    foreach ($items as $item) {
        if ($item === '.' || $item === '..') {
            continue;
        }
        $path = "$dir/$item";
